/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_interconsulta_2a09d325_inac` BEFORE UPDATE ON `interconsulta` FOR EACH ROW BEGIN IF LOWER(IFNULL(OLD.`estado`, '')) <> 'inactivo' AND LOWER(IFNULL(NEW.`estado`, '')) = 'inactivo' THEN INSERT INTO log_registros_inactivos (tabla_nombre, registro_pk_columna, registro_pk_valor, registro_resumen, estado_anterior, estado_nuevo, cod_usuario_accion, nombre_usuario_accion, fecha_accion, usuario_bd, datos_json) VALUES ('interconsulta', 'cod_interConsulta', NEW.`cod_interConsulta`, NEW.`asunto`, OLD.`estado`, NEW.`estado`, NEW.`cod_usuarioFK_edit`, (SELECT nombre_persona FROM persona WHERE cod_persona = NEW.`cod_usuarioFK_edit` LIMIT 1), NOW(), CURRENT_USER(), CONCAT('{"tabla":"', 'interconsulta', '","pk":"', NEW.`cod_interConsulta`, '"}')); END IF; END */;;
