/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_mensaje_2652eee0_inac` BEFORE UPDATE ON `mensaje` FOR EACH ROW BEGIN IF LOWER(IFNULL(OLD.`estado`, '')) <> 'inactivo' AND LOWER(IFNULL(NEW.`estado`, '')) = 'inactivo' THEN INSERT INTO log_registros_inactivos (tabla_nombre, registro_pk_columna, registro_pk_valor, registro_resumen, estado_anterior, estado_nuevo, cod_usuario_accion, nombre_usuario_accion, fecha_accion, usuario_bd, datos_json) VALUES ('mensaje', 'cod_mensaje', NEW.`cod_mensaje`, NULL, OLD.`estado`, NEW.`estado`, NEW.`cod_usuarioFK`, (SELECT nombre_persona FROM persona WHERE cod_persona = NEW.`cod_usuarioFK` LIMIT 1), NOW(), CURRENT_USER(), CONCAT('{"tabla":"', 'mensaje', '","pk":"', NEW.`cod_mensaje`, '"}')); END IF; END */;;
