/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_menciones_1601936b_inac` BEFORE UPDATE ON `menciones` FOR EACH ROW BEGIN IF LOWER(IFNULL(OLD.`estado`, '')) <> 'inactivo' AND LOWER(IFNULL(NEW.`estado`, '')) = 'inactivo' THEN INSERT INTO log_registros_inactivos (tabla_nombre, registro_pk_columna, registro_pk_valor, registro_resumen, estado_anterior, estado_nuevo, cod_usuario_accion, nombre_usuario_accion, fecha_accion, usuario_bd, datos_json) VALUES ('menciones', 'cod_mencion', NEW.`cod_mencion`, NULL, OLD.`estado`, NEW.`estado`, NEW.`cod_usuarioFK`, (SELECT nombre_persona FROM persona WHERE cod_persona = NEW.`cod_usuarioFK` LIMIT 1), NOW(), CURRENT_USER(), CONCAT('{"tabla":"', 'menciones', '","pk":"', NEW.`cod_mencion`, '"}')); END IF; END */;;
DELIMITER ;
