DROP TABLE IF EXISTS `gastos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gastos` (
  `idgastos` int NOT NULL AUTO_INCREMENT,
  `monto` double DEFAULT NULL,
  `motivo` varchar(150) DEFAULT NULL,
  `fecha` date DEFAULT NULL,
  `estado` varchar(45) DEFAULT NULL,
  `cod_usuario` int NOT NULL,
  `personales` varchar(75) NOT NULL,
  `cod_local` int NOT NULL DEFAULT '1',
  `tipo` varchar(45) DEFAULT NULL,
  `codCaja` varchar(45) NOT NULL,
  `codApertura` varchar(45) NOT NULL,
  `nrocuenta` varchar(45) DEFAULT NULL,
  `banco` varchar(75) DEFAULT NULL,
  `nroboleta` varchar(45) DEFAULT NULL,
  `arreglo` varchar(45) DEFAULT 'INTERNO',
  `cod_motivoIngresoEgresoFK` int DEFAULT NULL,
  `url1` varchar(100) DEFAULT NULL,
  `url_documento_firmado` varchar(255) DEFAULT NULL,
  `cod_motivo` int DEFAULT NULL,
  `cod_interConsultaFK` int DEFAULT NULL,
  `cod_usuario_autoriz` int DEFAULT NULL,
  `fecha_autoriz` datetime DEFAULT NULL,
  `cod_usuarioFK_edit` int DEFAULT NULL,
  `cod_mensajeFK` int DEFAULT NULL,
  `modalidad` enum('contado','credito') DEFAULT 'contado',
  `cod_gasto_padre` int DEFAULT NULL,
  `cod_proyecto_gastoFK` int DEFAULT NULL,
  PRIMARY KEY (`idgastos`),
  KEY `fk_gastos_local1_idx` (`cod_local`),
  KEY `fk_gastos_usuario1_idx` (`cod_usuario`),
  KEY `idx_gastos_codapertura_estado_tipo` (`codApertura`,`estado`,`tipo`),
  KEY `idx_gastos_interconsulta_estado` (`cod_interConsultaFK`,`estado`),
  KEY `idx_gastos_flujo_motivo_local_fecha_estado` (`cod_motivoIngresoEgresoFK`,`cod_local`,`fecha`,`estado`)
) ENGINE=InnoDB AUTO_INCREMENT=6646 DEFAULT CHARSET=utf8mb3;
