/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_gastos_inactivo` AFTER UPDATE ON `gastos` FOR EACH ROW BEGIN
    -- Validamos que el nuevo estado sea 'Inactivo'
    IF NEW.estado = 'Inactivo' THEN
        -- Actualizamos el mensaje asociado
        UPDATE mensaje
        SET estado = 'inactivo'
        WHERE cod_mensaje = NEW.cod_mensajeFK;
    END IF;
END */;;
